package tools; import ioc.*;import packet.*;import java.nio.file.Files;import java.nio.file.Path;import java.util.List; public final class IocMatch{public static void main(String[] args){try{if(args.length<2)throw new IllegalArgumentException("usage: iocmatch <ioc-file> <pcap-file>");List<Ioc> iocs=new IocParser().parse(Files.readAllBytes(Path.of(args[0]))).orNull();IocSet set=new IocSet();set.addAll(iocs);List<PacketMetadata> packets=new PacketInspector().inspectPcap(Files.readAllBytes(Path.of(args[1])));List<MatchResult> matches=new IocMatcher().match(set,packets);System.out.println(new IocReport().summarize(iocs));for(MatchResult m:matches)System.out.println(m.format());}catch(Exception e){CliSupport.exitOnError(e);}}}
